def migrar_opciones_json_a_campos_eval(apps, schema_editor):
    PasoModulo = apps.get_model('core', 'PasoModulo')
    for p in PasoModulo.objects.filter(tipo='evaluacion_opciones').iterator():
        data = p.opciones_json
        if not isinstance(data, dict):
            continue
        update = {}
        for letter in ('A', 'B', 'C', 'D'):
            col = f'eval_opcion_{letter.lower()}'
            if getattr(p, col, None):
                continue
            val = data.get(letter)
            if val:
                update[col] = str(val).strip()
        if update:
            PasoModulo.objects.filter(pk=p.pk).update(**update)


